#!/usr/bin/env python3
import json
import re
import sys

VERSION = "1.2.0"
USAGE = """Usage:
  python backfill_tool.py --help
  python backfill_tool.py --version
  python backfill_tool.py --config PATH greet NAME

Commands:
  greet NAME  Print a greeting for NAME.

Options:
  --config PATH  JSON configuration file used by greet.
  --help         Show this help text.
  --version      Show the tool version.

NAME must start with a letter and contain only letters, digits, underscore, or hyphen.
The configuration must contain exactly prefix and version, with version 1.2.0.
"""
NAME_PATTERN = re.compile(r"[A-Za-z][A-Za-z0-9_-]*\Z")


def fail(message):
    sys.stderr.write("error: " + message + "\n")
    return 2


def read_config(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except (OSError, json.JSONDecodeError):
        return None, "cannot read config: " + path
    if not isinstance(data, dict) or set(data) != {"prefix", "version"}:
        return None, "config must contain exactly prefix and version"
    if not isinstance(data["prefix"], str) or not data["prefix"]:
        return None, "config prefix must be a non-empty string"
    if data["version"] != VERSION:
        return None, "config version must be " + VERSION
    return data, None


def main(argv):
    if argv == ["--help"]:
        sys.stdout.write(USAGE)
        return 0
    if argv == ["--version"]:
        sys.stdout.write("backfill-tool " + VERSION + "\n")
        return 0
    if len(argv) != 4 or argv[0] != "--config" or argv[2] != "greet":
        return fail("expected --config PATH greet NAME; use --help")
    config, error = read_config(argv[1])
    if error:
        return fail(error)
    name = argv[3]
    if not NAME_PATTERN.fullmatch(name):
        return fail("NAME must start with a letter and contain only letters, digits, underscore, or hyphen")
    sys.stdout.write(config["prefix"] + ", " + name + "!\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
